			function switchResultsTab(tabName) {
				// Hide all tab contents
				document.querySelectorAll('.results-tab-content').forEach(content => {
					content.style.display = 'none';
					content.classList.remove('active');
				});
				
				// Deactivate all tab buttons
				document.querySelectorAll('.results-tab-btn').forEach(btn => {
					btn.classList.remove('active');
				});
				
				// Show active tab content
				const activeContent = document.getElementById(tabName + '-tab-content');
				if (activeContent) {
					activeContent.style.display = 'block';
					setTimeout(() => {
						activeContent.classList.add('active');
					}, 10);
				}
				
				// Find and activate the clicked button
				event.currentTarget.classList.add('active');
			}

			(function () {
				const slider = document.getElementById('ba-slider-botox');
				const beforeClip = document.getElementById('ba-before-clip-botox');
				const handle = document.getElementById('ba-handle-botox');
				const circle = handle.querySelector('.ba-handle-circle');

				let isDragging = false;

				function getPercent(clientX) {
					const rect = slider.getBoundingClientRect();
					let x = clientX - rect.left;
					x = Math.max(0, Math.min(x, rect.width));
					return (x / rect.width) * 100;
				}

				function updateSlider(percent) {
					const right = 100 - percent;
					beforeClip.style.clipPath = `inset(0 ${right}% 0 0)`;
					handle.style.left = percent + '%';
				}

				// Mouse Events
				slider.addEventListener('mousedown', function (e) {
					isDragging = true;
					circle.classList.add('dragging');
					updateSlider(getPercent(e.clientX));
					e.preventDefault();
				});

				window.addEventListener('mousemove', function (e) {
					if (!isDragging) return;
					updateSlider(getPercent(e.clientX));
				});

				window.addEventListener('mouseup', function () {
					if (!isDragging) return;
					isDragging = false;
					circle.classList.remove('dragging');
				});

				// Touch Events
				slider.addEventListener('touchstart', function (e) {
					isDragging = true;
					circle.classList.add('dragging');
					updateSlider(getPercent(e.touches[0].clientX));
				}, { passive: true });

				window.addEventListener('touchmove', function (e) {
					if (!isDragging) return;
					updateSlider(getPercent(e.touches[0].clientX));
				}, { passive: true });

				window.addEventListener('touchend', function () {
					if (!isDragging) return;
					isDragging = false;
					circle.classList.remove('dragging');
				});
			})();
		


		function toggleAccordionItem(element) {
			const item = element.closest('.accordion__item');
			const answer = item.querySelector('.accordion__answer');
			if (!item || !answer) return;
			
			const isOpen = item.classList.contains('open');
			
			const parentAccordion = item.closest('.accordion');
			if (parentAccordion) {
				parentAccordion.querySelectorAll('.accordion__item').forEach(i => {
					i.classList.remove('open');
					const a = i.querySelector('.accordion__answer');
					if (a) {
						a.style.maxHeight = '0px';
						a.style.opacity = '0';
					}
				});
			}
			
			if (!isOpen) {
				item.classList.add('open');
				answer.style.maxHeight = '500px';
				answer.style.opacity = '1';
			}
		}
	


